PRAGMA foreign_keys = ON;
CREATE TABLE Learner (learner_id TEXT PRIMARY KEY, learner_name TEXT NOT NULL, experience_level TEXT NOT NULL CHECK (experience_level IN ('Beginner','Intermediate','Advanced')), learner_status TEXT NOT NULL);
CREATE TABLE Course (course_id TEXT PRIMARY KEY, course_name TEXT NOT NULL, course_status TEXT NOT NULL);
CREATE TABLE Skill (skill_id TEXT PRIMARY KEY, skill_name TEXT NOT NULL, difficulty_level TEXT NOT NULL CHECK (difficulty_level IN ('Beginner','Intermediate','Advanced')));
CREATE TABLE SkillPrerequisite (prerequisite_id TEXT PRIMARY KEY, skill_id TEXT NOT NULL REFERENCES Skill(skill_id), prerequisite_skill_id TEXT NOT NULL REFERENCES Skill(skill_id), effective_from TEXT NOT NULL, effective_to TEXT, CHECK(skill_id <> prerequisite_skill_id), UNIQUE(skill_id, prerequisite_skill_id));
CREATE TABLE ContentItem (content_id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES Course(course_id), content_title TEXT NOT NULL, content_type TEXT NOT NULL, difficulty_level TEXT NOT NULL, duration_minutes INTEGER NOT NULL CHECK(duration_minutes > 0), content_status TEXT NOT NULL);
CREATE TABLE ContentSkill (content_skill_id TEXT PRIMARY KEY, content_id TEXT NOT NULL REFERENCES ContentItem(content_id), skill_id TEXT NOT NULL REFERENCES Skill(skill_id), UNIQUE(content_id,skill_id));
CREATE TABLE Attempt (attempt_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), content_id TEXT NOT NULL REFERENCES ContentItem(content_id), attempted_at TEXT NOT NULL, score REAL NOT NULL CHECK(score BETWEEN 0 AND 1), attempt_number INTEGER NOT NULL CHECK(attempt_number > 0), UNIQUE(learner_id,attempt_number));
CREATE TABLE AssessmentResult (assessment_id TEXT PRIMARY KEY REFERENCES Attempt(attempt_id), score REAL NOT NULL CHECK(score BETWEEN 0 AND 1), assessment_type TEXT NOT NULL);
CREATE TABLE Recommendation (recommendation_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), content_id TEXT NOT NULL REFERENCES ContentItem(content_id), skill_id TEXT NOT NULL REFERENCES Skill(skill_id), recommended_at TEXT NOT NULL, rank INTEGER NOT NULL, reason_code TEXT NOT NULL, mastery_at_recommendation REAL NOT NULL CHECK(mastery_at_recommendation BETWEEN 0 AND 1), status TEXT NOT NULL);
CREATE TABLE LearningPath (learning_path_id TEXT NOT NULL, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), sequence_no INTEGER NOT NULL, recommendation_id TEXT NOT NULL REFERENCES Recommendation(recommendation_id), created_at TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY(learning_path_id, sequence_no));
